import { test } from 'node:test';
import assert from 'node:assert/strict';
import { BufferSink, ChecksumFlag, Encoder } from '../../src/ltx/index.ts';

/**
 * Golden regression for the encoder's on-disk format.
 *
 * Our `compressBlock` is a byte-identical TypeScript port of Go's
 * `pierrec/lz4/v4` Fast block compressor, so the LTX files we write match Go's
 * `superfly/ltx` encoder exactly. The file checksums below are the canonical Go
 * golden vectors (generated by `tools/golden`):
 *   SparseNonSnapshot: 0xf61cfb1887ed139e
 *   Snapshot:          0x8433a627b12d0fd4
 * The post-apply checksums are Go's computed rolling checksum, required so the
 * file checksum (which covers the trailer) matches Go byte-for-byte.
 */

function makePage(seed: number): Uint8Array {
  const b = new Uint8Array(512);
  for (let i = 0; i < 512; i++) b[i] = (seed + (i % 7)) & 0xff;
  return b;
}

test('golden: SparseNonSnapshot file checksum (our encoder)', () => {
  const sink = new BufferSink();
  const enc = new Encoder(sink);
  enc.encodeHeader({
    version: 3,
    flags: 0,
    pageSize: 512,
    commit: 16,
    minTXID: 2n,
    maxTXID: 3n,
    timestamp: 1000n,
    preApplyChecksum: ChecksumFlag | 1n,
    walOffset: 0n,
    walSize: 0n,
    walSalt1: 0,
    walSalt2: 0,
    nodeID: 0n,
  });
  for (const pgno of [2, 5, 9, 16]) {
    enc.encodePage({ pgno, flags: 0 }, makePage(pgno));
  }
  enc.setPostApplyChecksum(0x962f504cc721a85an);
  enc.close();
  assert.equal(enc.Trailer().fileChecksum, 0xf61cfb1887ed139en);
  assert.equal(sink.length, 310);
});

test('golden: Snapshot file checksum (our encoder)', () => {
  const sink = new BufferSink();
  const enc = new Encoder(sink);
  enc.encodeHeader({
    version: 3,
    flags: 0,
    pageSize: 512,
    commit: 6,
    minTXID: 1n,
    maxTXID: 4n,
    timestamp: 1000n,
    preApplyChecksum: 0n,
    walOffset: 0n,
    walSize: 0n,
    walSalt1: 0,
    walSalt2: 0,
    nodeID: 0n,
  });
  for (let pgno = 1; pgno <= 6; pgno++) {
    enc.encodePage({ pgno, flags: 0 }, makePage(pgno));
  }
  enc.setPostApplyChecksum(0x8588a7d9e2e3c1f5n);
  enc.close();
  assert.equal(enc.Trailer().fileChecksum, 0x8433a627b12d0fd4n);
  assert.equal(sink.length, 400);
});

test('snapshot file is byte-identical to the Go golden', () => {
  // Our LZ4 port matches Go's `pierrec/lz4/v4` exactly, so the snapshot file
  // we write (with Go's computed post-apply checksum) reproduces Go's golden
  // file checksum and length byte-for-byte.
  const sink = new BufferSink();
  const enc = new Encoder(sink);
  enc.encodeHeader({
    version: 3,
    flags: 0,
    pageSize: 512,
    commit: 6,
    minTXID: 1n,
    maxTXID: 4n,
    timestamp: 1000n,
    preApplyChecksum: 0n,
    walOffset: 0n,
    walSize: 0n,
    walSalt1: 0,
    walSalt2: 0,
    nodeID: 0n,
  });
  for (let pgno = 1; pgno <= 6; pgno++) {
    enc.encodePage({ pgno, flags: 0 }, makePage(pgno));
  }
  enc.setPostApplyChecksum(0x8588a7d9e2e3c1f5n);
  enc.close();
  assert.equal(enc.Trailer().fileChecksum, 0x8433a627b12d0fd4n);
  assert.equal(sink.length, 400);
});
